+.page-shell { width: min(1400px, calc(100% - 48px)); margin: 0 auto; padding: 34px 0 28px; }
+.page-header { margin: 0 0 22px; }
+.eyebrow { margin: 0 0 7px; color: #54816e; font-size: .7rem; font-weight: 800; letter-spacing: .12em; }
+h1, h2, p { margin-top: 0; }
+h1 { margin-bottom: 8px; color: #18352d; font-size: clamp(2rem, 4vw, 3rem); letter-spacing: -.045em; line-height: 1.02; }
+h2 { margin-bottom: 0; color: #213b33; font-size: 1.08rem; letter-spacing: -.02em; }
