+.card-note { margin: 13px 0 16px; color: #708079; font-size: .8rem; line-height: 1.5; }
+code { border-radius: 4px; padding: 1px 4px; background: #eff4f1; color: #3c6956; font-size: .94em; }
+.go-view { min-height: 270px; border: 1px solid #e1e9e5; border-radius: 12px; padding: 17px; background: linear-gradient(145deg, #f9fbfa, #f2f7f4); }
+.host-controls { display: flex; align-items: center; justify-content: space-between; gap: 18px; margin-top: 16px; border-top: 1px solid #e4ebe7; padding-top: 15px; }
