+.inspector-card .data-panel { max-height: 195px; }
+.trace-card { margin-top: 18px; padding: 18px 20px; }
+.trace-card .card-heading { margin-bottom: 12px; }
+.trace-hint { color: #688075; font-size: .75rem; text-align: right; }
+.trace-panel { max-height: 360px; white-space: pre; }
+.page-footer { display: flex; justify-content: space-between; gap: 14px; margin-top: 15px; color: #819089; font-size: .73rem; }
+
+/* The compiled Go View uses the fixture's semantic classes. Keep its structure visible without replacing its controls. */
+.go-view [data-view] { color: #253d35; }
+.go-view .lifecycle-node, .go-view [data-component] { border: 1px solid #d7e5dd; border-radius: 11px; padding: 12px; background: #fff; }
+.go-view .lifecycle-parent { background: #f4faf6; }
+.go-view .lifecycle-children { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 10px; margin: 10px 0 0 15px; }
+.go-view .lifecycle-grandchild { margin: 9px 0 0 14px; background: #fafcfb; }
+.go-view .lifecycle-sibling { margin-top: 11px; border-left: 3px solid #8ebda4; }
+.go-view button { margin: 3px 4px 3px 0; }
+.go-view p { margin-bottom: 6px; }
+.go-view .lifecycle-controls { margin-top: 14px; border-top: 1px dashed #cedbd4; padding-top: 10px; }
+
+@media (max-width: 940px) {
+  .workspace { grid-template-columns: 1fr; }
+  .inspector { grid-template-columns: repeat(3, minmax(0, 1fr)); }
+  .inspector-card { min-width: 0; }
+}
+
+@media (max-width: 650px) {
+  .page-shell { width: min(100% - 28px, 520px); padding-top: 22px; }
+  .inspector { grid-template-columns: 1fr; }
+  .inspector-card .data-panel { max-height: 220px; }
+  .card-heading, .host-controls, .page-footer { align-items: flex-start; flex-direction: column; }
+  .trace-hint { text-align: left; }
+}

